:root { --b-100: #f2f3f7; --s-700: #37546d; }

/* Added for the blog index reference clone (src/components/sites/chatwoot/blog-clone):
   the ".hero"/".hero__grid"/".hero__content" classes (data-v-0f12600f) style the blog
   index hero and weren't present in this compiled snapshot (only classes from
   previously-cloned pages are). Reconstructed from the live chatwoot.com/blog layout:
   .hero__content was "position:absolute" with no offsets, collapsing the section to 0
   height; switched it to static flow inside a relatively-positioned, padded .hero. */

/* Página de preços (Pricing.tsx). Escopo .tp para não colidir com chatwoot.css.
   Fontes Haskoy/Inter vêm do @font-face de chatwoot.css. */
.tp {
  --tp-blue: #1875ee;
  --tp-link: #086de0;
  --tp-blue-ink: #0f2459;
  --tp-ink: #1c2024;
  --tp-muted: #60646c;
  --tp-line: #e6e8eb;
  --tp-soft: #f5f8fe;
  --tp-soft-2: #eaf1fd;
  font-family: Inter, "Inter Fallback", -apple-system, sans-serif;
  color: var(--tp-ink);
  background: #fff;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}
.tp h1, .tp h2, .tp h3, .tp .tp-ff { font-family: Haskoy, "Haskoy Fallback", Inter, sans-serif; letter-spacing: -0.02em; margin: 0; }
.tp p { margin: 0; }
.tp a { color: inherit; text-decoration: none; }
.tp-wrap { max-width: 1140px; margin: 0 auto; padding: 0 24px; }

.tp-btn { font-size: 14px; font-weight: 600; padding: 10px 16px; border-radius: 9px; cursor: pointer; display: inline-block; transition: 0.15s; }
.tp-btn-outline { border: 1px solid var(--tp-blue); color: var(--tp-blue) !important; }
.tp-btn-outline:hover { background: var(--tp-soft-2); }
.tp-btn-primary { background: var(--tp-blue); color: #fff !important; }
.tp-btn-primary:hover { background: #1366d6; }

.tp-hero { text-align: center; padding: 64px 0 10px; }
.tp-eyebrow { display: inline-block; font-size: 12px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase; color: var(--tp-blue); background: var(--tp-soft-2); padding: 6px 14px; border-radius: 999px; margin-bottom: 18px; }
.tp-hero h1 { font-size: 46px; font-weight: 700; line-height: 1.05; max-width: 20ch; margin: 0 auto; }
.tp-hero p { font-size: 17px; color: var(--tp-muted); max-width: 60ch; margin: 16px auto 0; }
.tp-hero p b { color: var(--tp-ink); }

.tp-cards { display: grid; grid-template-columns: repeat(4, 1fr); gap: 18px; margin-top: 46px; align-items: start; }
.tp-card { border: 1px solid var(--tp-line); border-radius: 18px; padding: 26px 24px; background: #fff; display: flex; flex-direction: column; min-height: 100%; }
.tp-card.tp-hl { border: 2px solid var(--tp-blue); box-shadow: 0 18px 44px rgba(24, 117, 238, 0.16); position: relative; }
.tp-ptop { display: flex; align-items: center; justify-content: space-between; min-height: 26px; }
.tp-pname { font-size: 19px; font-weight: 700; }
.tp-badge { font-size: 11px; font-weight: 700; letter-spacing: 0.03em; text-transform: uppercase; color: #fff; background: var(--tp-blue); padding: 5px 11px; border-radius: 999px; }
.tp-pdesc { font-size: 13.5px; color: var(--tp-muted); margin-top: 6px; min-height: 38px; }
.tp-price { margin: 16px 0 2px; display: flex; align-items: baseline; gap: 5px; }
.tp-cur { font-size: 18px; font-weight: 600; }
.tp-val { font-family: Haskoy, "Haskoy Fallback", sans-serif; font-size: 44px; font-weight: 700; line-height: 1; }
.tp-per { font-size: 14px; color: var(--tp-muted); }
.tp-cta { margin: 20px 0 4px; text-align: center; width: 100%; }
.tp-spec { list-style: none; margin: 16px 0 0; border-top: 1px solid var(--tp-line); padding: 16px 0 0; }
.tp-lbl { font-size: 12px; font-weight: 600; letter-spacing: 0.03em; text-transform: uppercase; color: var(--tp-muted); margin-bottom: 8px; }
.tp-spec li { display: flex; align-items: flex-start; gap: 9px; font-size: 14px; padding: 5px 0; }
.tp-spec li svg { width: 16px; height: 16px; flex: 0 0 16px; margin-top: 2px; color: var(--tp-blue); }
.tp-spec li b { font-weight: 600; }

.tp-section { padding: 72px 0 0; }
.tp-section h2 { font-size: 32px; font-weight: 700; text-align: center; }
.tp-sub { text-align: center; color: var(--tp-muted); font-size: 15px; margin-top: 10px !important; }
.tp-sub a { color: var(--tp-link) !important; font-weight: 600; }
.tp-tablewrap { overflow-x: auto; margin-top: 36px; }
.tp-cmp { width: 100%; border-collapse: collapse; font-size: 14.5px; }
.tp-cmp th, .tp-cmp td { padding: 14px 16px; text-align: center; border-bottom: 1px solid var(--tp-line); }
.tp-cmp thead th { font-family: Haskoy, "Haskoy Fallback", sans-serif; font-size: 16px; font-weight: 700; border-bottom: 2px solid var(--tp-ink); }
.tp-cmp .tp-feat { text-align: left; }
.tp-cmp td.tp-feat { font-weight: 500; }
.tp-cmp thead th.tp-hl { color: var(--tp-blue); }
.tp-cmp td.tp-hl { background: var(--tp-soft); }
.tp-cmp tr.tp-grp td { background: var(--tp-soft); font-family: Haskoy, "Haskoy Fallback", sans-serif; font-weight: 700; font-size: 13px; letter-spacing: 0.03em; text-transform: uppercase; color: var(--tp-blue-ink); text-align: left; }
.tp-ck { color: var(--tp-blue); }

.tp-addons { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 40px; }
.tp-addon { border: 1px solid var(--tp-line); border-radius: 14px; padding: 22px; text-align: center; }
.tp-addon-n { font-size: 15px; font-weight: 600; }
.tp-addon-p { font-family: Haskoy, "Haskoy Fallback", sans-serif; font-size: 26px; font-weight: 700; margin-top: 6px; }
.tp-addon-d { font-size: 13px; color: var(--tp-muted); margin-top: 4px; }

.tp-faq { max-width: 760px; margin: 36px auto 0; }
.tp-faq details { border-bottom: 1px solid var(--tp-line); padding: 18px 0; }
.tp-faq summary { font-family: Haskoy, "Haskoy Fallback", sans-serif; font-size: 17px; font-weight: 600; cursor: pointer; list-style: none; display: flex; justify-content: space-between; align-items: center; gap: 16px; }
.tp-faq summary::-webkit-details-marker { display: none; }
.tp-faq summary::after { content: "+"; font-size: 22px; color: var(--tp-blue); font-weight: 400; }
.tp-faq details[open] summary::after { content: "\2013"; }
.tp-faq details p { font-size: 14.5px; color: var(--tp-muted); margin-top: 12px; max-width: 68ch; }

.tp-band { margin: 72px 0; background: var(--tp-blue-ink); border-radius: 22px; padding: 48px; text-align: center; color: #fff; }
.tp-band h2 { color: #fff; font-size: 30px; font-weight: 700; }
.tp-band p { color: #c7d6f5; font-size: 16px; margin: 12px auto 24px; max-width: 52ch; }
.tp-btn-white { background: #fff; color: var(--tp-blue-ink) !important; font-weight: 700; }
.tp-btn-white:hover { background: #eaf1fd; }

@media (max-width: 1100px) {
  .tp-cards { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 900px) {
  .tp-cards, .tp-addons { grid-template-columns: 1fr; }
  .tp-hero h1 { font-size: 34px; }
  .tp-cmp { font-size: 12.5px; }
  .tp-cmp th, .tp-cmp td { padding: 10px 8px; }
  .tp-band { padding: 36px 22px; }
}
.tp-val-custom { font-size: 28px; }
.tp-spec-list { list-style: none; margin: 0; padding: 0; }

/* Blog views (list, post, page) styled with the clone's design tokens. */
body { background: #fff; color: #1c2024; font-family: var(--font-body); }
/* The mount point must not become the sticky header's containing block. */
#cw-header, #cw-footer { display: contents; }
#cw-header:empty { display: block; height: 61px; border-bottom: 1px solid #ededf0; }

.cwb-main { margin: 0; }
.cwb-section { border-bottom: 1px solid #ededf0; }
.cwb-frame { max-width: 1200px; margin: 0 auto; border-left: 1px solid #f0f0f2; border-right: 1px solid #f0f0f2; }
.cwb-head { padding: clamp(36px, 4vw, 56px) 24px clamp(22px, 2.6vw, 30px); border-bottom: 1px solid #ededf0; }
.cwb-eyebrow { margin: 0 0 10px; font-family: var(--font-label); font-size: 11px; letter-spacing: .14em; text-transform: uppercase; color: #6e7279; }
.cwb-title { margin: 0; font-family: var(--font-brand); font-weight: 700; font-size: clamp(26px, 3vw, 38px); line-height: 1.08; letter-spacing: -.035em; color: #1c2024; text-wrap: balance; }
.cwb-sub { margin: 10px 0 0; max-width: 60ch; font-size: 15.5px; line-height: 1.6; color: #60646c; }

.cwb-layout { display: grid; grid-template-columns: 1fr; }
.cwb-sidebar { padding: 28px 24px; border-bottom: 1px solid #ededf0; }
.cwb-sidebar-label { margin: 0 0 8px; font-family: var(--font-label); font-size: 11px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: #6e7279; }
.cwb-topics { display: flex; flex-direction: column; gap: 6px; }
.cwb-topic { display: block; padding: 8px 12px; border-radius: 6px; box-shadow: inset 0 0 0 1px #e3e4e8; font-family: var(--font-label); font-size: 14px; font-weight: 500; color: #1c2024; text-decoration: none; }
.cwb-topic:hover { box-shadow: inset 0 0 0 1px #c9cdd3; }
.cwb-topic--active { background: #1c2024; color: #fff; font-weight: 600; box-shadow: none; }
.cwb-topic--active:hover { box-shadow: none; }
.cwb-main-col { min-width: 0; padding: 28px 24px; }

.cwb-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 1px; background: #ededf0; border-radius: 10px; overflow: hidden; box-shadow: inset 0 0 0 1px #e6e8eb; }
.cwb-card { display: flex; flex-direction: column; background: #fff; transition: background-color .15s ease-out; }
.cwb-card:hover { background: #fbfcfd; }
.cwb-thumb { position: relative; display: block; aspect-ratio: 16/9; overflow: hidden; background: #f4f5f7; }
.cwb-thumb img { display: block; width: 100%; height: 100%; object-fit: cover; transition: transform .35s ease-out; }
.cwb-card:hover .cwb-thumb img { transform: scale(1.03); }
.cwb-thumb-empty { position: absolute; inset: 0; background-color: #fbfcfd; background-image: radial-gradient(#c4d6f8 1px, transparent 1.4px); background-size: 10px 10px; opacity: .8; }
.cwb-card-body { display: flex; flex: 1; flex-direction: column; gap: 10px; padding: 18px 20px 22px; }
.cwb-tag { align-self: flex-start; display: inline-flex; height: 24px; align-items: center; padding: 0 9px; border-radius: 999px; background: #eaf3ff; color: #0f2459; font-family: var(--font-label); font-size: 12px; font-weight: 600; text-decoration: none; }
.cwb-tag:hover { background: #dce7fa; }
.cwb-card-title { margin: 0; font-family: var(--font-brand); font-weight: 700; font-size: 17px; line-height: 1.3; letter-spacing: -.015em; }
.cwb-card-title a { color: #1c2024; text-decoration: none; }
.cwb-card-title a:hover { color: #086de0; }
.cwb-snippet { margin: 0; font-size: 14px; line-height: 1.55; color: #60646c; }
.cwb-meta { margin-top: auto; display: flex; align-items: center; gap: 8px; padding-top: 4px; font-family: var(--font-label); font-size: 12.5px; color: #80838d; }
.cwb-empty { padding: 48px 0; background: #fff; color: #60646c; }

/* First post in the grid reads as the featured/highlighted story. */
.cwb-grid > .cwb-card:first-child { grid-column: 1 / -1; background: #fff; box-shadow: inset 0 0 0 1px #e6e8eb; }
@media (min-width: 641px) {
  .cwb-grid > .cwb-card:first-child { flex-direction: row; }
  .cwb-grid > .cwb-card:first-child .cwb-thumb { width: 40%; flex: none; }
  .cwb-grid > .cwb-card:first-child .cwb-card-body { flex: 1; justify-content: center; }
  .cwb-grid > .cwb-card:first-child .cwb-card-title { font-size: 24px; }
}

.cwb-pager { display: flex; justify-content: space-between; gap: 12px; padding: 20px 0; }
.cwb-pager a { display: inline-flex; align-items: center; height: 36px; padding: 0 16px; border-radius: 6px; background: #fff; color: #1c2024; font-size: 14px; font-weight: 600; text-decoration: none; box-shadow: inset 0 0 0 1px #d9dbe0, 0 1px 2px rgba(28, 32, 36, .06); }
.cwb-pager a:hover { background: #f6f6f8; }
.cwb-pager .cwb-older { margin-inline-start: auto; }

.cwb-newsletter { margin-top: 24px; padding: 32px; border-radius: 10px; background: #fbfcfd; box-shadow: inset 0 0 0 1px #e6e8eb; }
.cwb-newsletter h2 { margin: 0; font-family: var(--font-brand); font-weight: 700; font-size: 22px; letter-spacing: -.02em; color: #1c2024; }
.cwb-newsletter p { margin: 6px 0 0; font-size: 14.5px; line-height: 1.55; color: #60646c; }
.cwb-newsletter-form { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 20px; }
.cwb-newsletter-form input { height: 44px; min-width: 240px; flex: 1 1 240px; border: 0; border-radius: 6px; padding: 0 14px; font-size: 15px; color: #1c2024; box-shadow: inset 0 0 0 1px #e3e4e8; }
.cwb-newsletter-form input:focus { outline: 2px solid #1875ee; outline-offset: 1px; }
.cwb-newsletter-form button { height: 44px; padding: 0 20px; border: 0; border-radius: 6px; background: #1875ee; color: #fff; font-size: 14px; font-weight: 600; cursor: pointer; }
.cwb-newsletter-form button:hover { filter: brightness(1.1); }

/* O padding horizontal fica DENTRO do frame: senao breadcrumb/titulo/selo
   encostam na linha vertical (o frame e filho do header, nao o contrario). */
.cwb-post-head { padding: clamp(28px, 3.4vw, 44px) 0 clamp(28px, 3vw, 40px); border-bottom: 1px solid #ededf0; }
.cwb-post-head > .cwb-frame { padding-left: 24px; padding-right: 24px; }
.cwb-post-head .cwb-title { margin-top: clamp(28px, 3.4vw, 44px); font-size: clamp(32px, 3.6vw, 48px); line-height: 1.05; letter-spacing: -.04em; max-width: 24ch; }
.cwb-post-head .cwb-meta { margin-top: 18px; }
.cwb-breadcrumb { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; font-family: var(--font-label); font-size: 13px; font-weight: 500; }
.cwb-breadcrumb-home, .cwb-breadcrumb-link { display: inline-flex; align-items: center; color: #80838d; text-decoration: none; }
.cwb-breadcrumb-home:hover, .cwb-breadcrumb-link:hover { color: #1c2024; }
.cwb-breadcrumb-sep { display: inline-flex; align-items: center; color: #b0b4ba; }
.cwb-breadcrumb-sep svg { display: block; width: 14px; height: 14px; }
.cwb-breadcrumb-current { color: #1c2024; max-width: 60vw; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cwb-labels { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 14px; }
.cwb-cover { margin: 0; padding: 24px; border-bottom: 1px solid #ededf0; }
.cwb-cover img { display: block; width: 100%; max-height: 560px; object-fit: cover; border-radius: 10px; box-shadow: inset 0 0 0 1px #e6e8eb; }

.cwb-post-layout { display: grid; grid-template-columns: 1fr; }
.cwb-post-aside { padding: 24px; border-bottom: 1px solid #ededf0; }
.cwb-post-aside-sticky { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 18px 24px; }
.cwb-post-author { display: flex; align-items: center; gap: 12px; }
.cwb-avatar { display: grid; place-items: center; width: 40px; height: 40px; flex: none; border-radius: 8px; background: #2781f6; color: #fff; }
.cwb-author-name { margin: 0; font-family: var(--font-label); font-weight: 600; font-size: 14px; color: #1c2024; }
.cwb-author-date { margin: 0; font-family: var(--font-label); font-weight: 500; font-size: 13px; color: #60646c; }
.cwb-readtime { display: flex; align-items: center; gap: 8px; font-family: var(--font-label); font-weight: 500; font-size: 13px; color: #60646c; }
.cwb-share { display: flex; align-items: center; gap: 2px; margin-inline-start: -6px; color: #60646c; }
.cwb-share-btn { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 6px; color: inherit; }
.cwb-share-btn:hover { background: #f2f3f5; color: #1c2024; }
.cwb-post-body-col { min-width: 0; padding: 28px 24px; }

.cwb-prose { max-width: 720px; font-size: 17px; line-height: 1.75; color: #2b2f36; }
.cwb-prose > :first-child { margin-top: 0; }
.cwb-prose h1, .cwb-prose h2, .cwb-prose h3, .cwb-prose h4 { font-family: var(--font-brand); color: #1c2024; letter-spacing: -.025em; line-height: 1.2; margin: 1.8em 0 .6em; }
.cwb-prose h2 { font-size: 30px; font-weight: 700; }
.cwb-prose h3 { font-size: 23px; font-weight: 600; }
.cwb-prose h4 { font-size: 19px; font-weight: 600; }
.cwb-prose p, .cwb-prose ul, .cwb-prose ol, .cwb-prose blockquote, .cwb-prose pre, .cwb-prose table, .cwb-prose figure { margin: 0 0 1.25em; }
.cwb-prose ul, .cwb-prose ol { padding-inline-start: 1.4em; }
.cwb-prose ul { list-style: disc; }
.cwb-prose ol { list-style: decimal; }
.cwb-prose li { margin: .35em 0; }
.cwb-prose a { color: #1875ee; text-decoration: underline; text-underline-offset: 3px; }
.cwb-prose a:hover { color: #086de0; }
.cwb-prose img { max-width: 100%; height: auto; border-radius: 8px; }
.cwb-prose .separator a { display: inline-block; }
.cwb-prose blockquote { padding: 4px 0 4px 18px; border-inline-start: 3px solid #1875ee; color: #3f434a; font-style: italic; }
.cwb-prose code { padding: .15em .4em; border-radius: 5px; background: #f4f5f7; font-size: .9em; }
.cwb-prose pre { overflow-x: auto; padding: 16px 18px; border-radius: 10px; background: #1c2024; color: #f4f5f7; font-size: 14px; line-height: 1.6; }
.cwb-prose pre code { padding: 0; background: none; }
.cwb-prose hr { margin: 2.4em 0; border: 0; border-top: 1px solid #ededf0; }
.cwb-prose table { width: 100%; border-collapse: collapse; font-size: 15px; }
.cwb-prose th, .cwb-prose td { padding: 10px 12px; border: 1px solid #ededf0; text-align: start; }
.cwb-prose th { background: #fbfcfd; font-weight: 600; }
.cwb-prose iframe, .cwb-prose video { max-width: 100%; border-radius: 8px; }

.cwb-comments { padding: 28px 24px 48px; border-top: 1px solid #ededf0; }
.cwb-comments .comments { max-width: 720px; }
.cwb-comments h3, .cwb-comments h4 { font-family: var(--font-brand); font-size: 22px; font-weight: 600; letter-spacing: -.02em; }
.cwb-comments .comment-content { font-size: 15px; line-height: 1.6; color: #2b2f36; }
.cwb-comments .comment-block { padding: 14px 0; border-bottom: 1px solid #ededf0; }
.cwb-comments .avatar-image-container img { border-radius: 8px; }

@media (min-width: 1024px) {
  .cwb-layout { grid-template-columns: 240px minmax(0, 1fr); }
  .cwb-sidebar { padding: 32px 24px; border-bottom: 0; border-inline-end: 1px solid #ededf0; }
  .cwb-sidebar-sticky { position: sticky; top: 7rem; }
  .cwb-main-col { padding: 32px 24px; }
  .cwb-post-layout { grid-template-columns: 260px minmax(0, 1fr); }
  .cwb-post-aside { padding: 40px 24px; border-bottom: 0; border-inline-end: 1px solid #ededf0; }
  .cwb-post-aside-sticky { position: sticky; top: 7rem; flex-direction: column; align-items: flex-start; }
  .cwb-post-body-col { padding: 40px 24px 40px 48px; }
}

@media (max-width: 640px) {
  .cwb-grid { grid-template-columns: 1fr; }
  .cwb-card-body { padding: 16px 20px 22px; }
  .cwb-prose { font-size: 16px; }
}


/* Tendly: oculta a estrutura padrao do Contempo */
#search_top, .section#header, #page_list_top, #ads, .section#footer,
#sidebar_top, #sidebar_bottom, .widget.FeaturedPost, .widget.PopularPosts,
.widget.Attribution, .widget.BlogSearch, .widget.Header, .widget.PageList { display: none !important; }
.widget.Blog { display: block; }
.skip-navigation, .centered-top-placeholder, .centered-top-container,
.bg-photo-overlay, .bg-photo-container, .vertical-ad-container, .main-heading,
.sidebar-container, .sidebar_top_wrapper, .sidebar-back, #comments, .comments,
#blog-pager, .blog-pager, .post-feeds { display: none !important; }
.page, .page_body, .centered, .centered-bottom, #main, .main.section {
  max-width: none !important; width: auto !important; margin: 0 !important;
  padding: 0 !important; background: transparent !important;
  box-shadow: none !important; border: 0 !important; float: none !important;
}

head.b:template-skin:

body#layout .hidden,
body#layout .invisible {
  display: inherit;
}
body#layout .navigation {
  display: none;
}
body#layout .page,
body#layout .sidebar_top,
body#layout .sidebar_bottom {
  display: inline-block;
  left: inherit;
  position: relative;
  vertical-align: top;
}
body#layout .page {
  float: right;
  margin-left: 20px;
  width: 55%;
}
body#layout .sidebar-container {
  float: right;
  width: 40%;
}
body#layout .hamburger-menu {
  display: none;
}
